// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const OPEN_LERP = 0.14;

/**
 * Drives `--bloom-open` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "the bloom" section. As you scroll the pinned flower stays put while
 * `--bloom-open` rises from 0 (a closed bud, petals scaled to 0.42 and
 * rotated -8°) to 1 (fully open, petals at scale 1, rotation 0°). The
 * section's height in CSS is taller than the viewport on purpose (a sticky
 * inner), so the progress maps cleanly onto a few screens of scroll.
 *
 * The CSS fallback is `var(--bloom-open, 1)` — fully open — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * signature flower simply stands open. The lerp makes it scrubbable without
 * jitter: scrolling fast opens fast, scrolling slow opens slow, and
 * scrolling back up closes the flower again.
 *
 * The scroll handler is passive and only writes to a CSS custom property
 * (no layout work); the rAF loop runs only while the section is on screen
 * and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--bloom-open", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * OPEN_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--bloom-open", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully open)
      el.style.removeProperty("--bloom-open");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { usePointerParallax } from "./hooks/usePointerParallax";

const TITLE = "PRISM";
// Spectrum data — wavelength (nm) and refractive index n for crown glass
// (BK7 ~1.51 at 589 nm). Shorter wavelengths refract more, so violet bends
// furthest from the incident beam. The legend reads as a lab chart.
const SPECTRUM = [
  { color: "#ef4444", ko: "적", en: "red",    deg: 0,   nm: 700, n: "1.513" },
  { color: "#f97316", ko: "주", en: "orange", deg: 30,  nm: 620, n: "1.515" },
  { color: "#eab308", ko: "황", en: "yellow", deg: 60,  nm: 580, n: "1.517" },
  { color: "#22c55e", ko: "녹", en: "green",  deg: 90,  nm: 530, n: "1.519" },
  { color: "#06b6d4", ko: "청", en: "cyan",   deg: 120, nm: 490, n: "1.522" },
  { color: "#3b82f6", ko: "람", en: "blue",   deg: 150, nm: 450, n: "1.524" },
  { color: "#8b5cf6", ko: "자", en: "violet", deg: 180, nm: 410, n: "1.530" },
];

/**
 * PRISM — 프리즘, 빛의 굴절 스튜디오. Glass-futurism entry where a beam of
 * white light passes through a glass prism SVG and refracts into a spectrum.
 * The signature: svg-line-draw (the light beam + spectrum rays draw via
 * stroke-dashoffset on scroll), pointer-parallax (the prism tilts toward the
 * pointer), char-split-reveal (the title glyphs split in).
 */
export default function PrismPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = usePointerParallax<HTMLDivElement>(reduced);

  useEffect(() => {
    rootRef.current?.classList.add("prism-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "prism" }, "*");
  }, []);

  return (
    <div
      ref={rootRef}
      className={`${inter.variable} ${notoSansKR.variable} prism-root`}
    >
      <div ref={revealRef} className="prism-doc">
        <header className="prism-hero">
          <p className="prism-kicker">
            <span lang="ko">빛의 굴절 스튜디오</span> · LIGHT REFRACTION STUDIO
          </p>
          <h1 className="prism-title" aria-label="PRISM 프리즘">
            {TITLE.split("").map((ch, i) => (
              <span
                key={i}
                aria-hidden="true"
                className="prism-glyph"
                style={{ "--prism-i": i, "--prism-c": SPECTRUM[i % SPECTRUM.length].color } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </h1>
          <p className="prism-sub">
            <span lang="ko">유리가 빛을 스펙트럼으로 쪼갠다.</span> Glass splits
            light into spectrum.
          </p>
        </header>

        {/* The prism scene — pointer-parallax + svg-line-draw */}
        <section ref={stageRef} className="prism-stage" data-reveal="">
          {/* A generated spectrum-beam render behind the SVG refraction — the
              ambient dispersed light of the glass studio, so the stage reads
              as a real light-room, not a flat card. The SVG line-draw stays
              the focal diagram. */}
          <img
            className="prism-stage__field"
            src="/media/prism/spectrum-beam.avif"
            alt=""
            aria-hidden="true"
            draggable="false"
          />
          <svg
            className="prism-beam-svg"
            viewBox="0 0 800 400"
            role="img"
            aria-labelledby="prism-beam-label"
          >
            <title id="prism-beam-label">
              프리즘이 빛을 굴절시킨다 — 흰 빛이 일곱 색으로 갈라진다. The prism refracts light — white splits into seven colors.
            </title>
            {/* incoming white beam */}
            <line
              className="prism-beam-in"
              x1="40" y1="200" x2="340" y2="200"
              stroke="#f8fafc" strokeWidth="4"
            />
            {/* the glass prism triangle */}
            <polygon
              className="prism-glass"
              points="340,140 420,260 260,260"
              fill="rgba(255,255,255,0.06)"
              stroke="rgba(255,255,255,0.3)"
              strokeWidth="1.5"
            />
            {/* outgoing spectrum rays */}
            {SPECTRUM.map((s, i) => (
              <line
                key={i}
                className="prism-ray"
                x1="340" y1="200"
                x2={760} y2={200 + (i - 3) * 28}
                stroke={s.color}
                strokeWidth="3"
                style={{ "--prism-ray-i": i } as CSSProperties}
              />
            ))}
          </svg>
        </section>

        {/* spectrum legend */}
        <section className="prism-spectrum" data-reveal="">
          <h2 className="prism-secthead">
            <span lang="ko">스펙트럼</span> · SPECTRUM
          </h2>
          <div className="prism-spectrum-grid">
            {SPECTRUM.map((s) => (
              <div key={s.en} className="prism-color" style={{ "--prism-c": s.color } as CSSProperties}>
                <span className="prism-color__swatch" />
                <p className="prism-color__ko" lang="ko">{s.ko}</p>
                <p className="prism-color__en">{s.en}</p>
                <p className="prism-color__data">
                  <span><b>{s.nm}</b> nm</span>
                  <span>n = <b>{s.n}</b></span>
                </p>
              </div>
            ))}
          </div>
        </section>

        <footer className="prism-foot" data-reveal="">
          <p>© 2026 PRISM · <span lang="ko">프리즘</span> · MIT</p>
          <p>
            <span lang="ko">코드로 그렸다 — 빛은 멈추지 않는다.</span> drawn in
            code — light never stops.
          </p>
        </footer>
      </div>
    </div>
  );
}

/* ==========================================================================
   PRISM 프리즘 — light refraction studio · glass-futurism
   glass white / spectrum / cyan accent · glass panels that split light
   Scoped by convention to .prism-root; classes prefixed prism-.
   Crafted to the gallery glass-futurism benchmark (see CRAFT-STANDARDS.md).
   ========================================================================== */

.prism-root {
  /* ---- Surface colors --------------------------------------------------
     Contrast ratios verified against the light gradient ground
     (#f8fafc → #eef2ff, treated as ~#f4f6fd for measurement).              */
  --prism-bg:           #f8fafc;  /* ground — paper white                  */
  --prism-bg-deep:      #eef2ff;  /* ground variant — indigo mist           */
  --prism-ink:          #1e293b;  /* slate-800 · ink on ground 13.0:1 (AAA) */
  --prism-ink-soft:     #475569;  /* slate-600 · ink on ground  7.7:1 (AAA) */
  --prism-accent:       #06b6d4;  /* cyan-500  · on ground 2.3:1 — large/
                                    decorative only; never body text        */
  --prism-accent-ink:   #0e7490;  /* cyan-700  · on ground 4.8:1 (AA-large) */
  --prism-glass:        rgba(255, 255, 255, 0.60);  /* glass surface alpha  */
  --prism-glass-deep:   rgba(255, 255, 255, 0.75);  /* hover/active lift    */
  --prism-glass-border: rgba(30, 41, 59, 0.10);     /* hairline edge        */
  --prism-glass-edge:   rgba(255, 255, 255, 0.65);  /* inner light edge     */

  /* ---- 4px baseline spacing scale ------------------------------------ */
  --sp-1:  0.25rem;   /*  4px */
  --sp-2:  0.5rem;    /*  8px */
  --sp-3:  0.75rem;   /* 12px */
  --sp-4:  1rem;      /* 16px */
  --sp-5:  1.25rem;   /* 20px */
  --sp-6:  1.5rem;    /* 24px */
  --sp-8:  2rem;      /* 32px */
  --sp-10: 2.5rem;    /* 40px */
  --sp-12: 3rem;      /* 48px */

  /* ---- Intent-separated easing curves --------------------------------
     Never default ease/linear — see CRAFT-STANDARDS §1.                   */
  --prism-ease-reveal: cubic-bezier(0.16, 1, 0.3, 1);    /* entry / reveal */
  --prism-ease-out:    cubic-bezier(0.25, 1, 0.5, 1);    /* hover / scrub  */
  --prism-ease-back:   cubic-bezier(0.34, 1.56, 0.64, 1);/* glyph overshoot*/
  --prism-ease-spread: cubic-bezier(0.7, 0, 0.2, 1);     /* clip curtains   */

  /* ---- Multi-layer glass shadow (ambient + key + contact) ------------- */
  --prism-shadow-stage:
    0 1px 2px   rgba(30, 41, 59, 0.04),    /* ambient — surface contact    */
    0 12px 28px rgba(30, 41, 59, 0.10),    /* key — primary cast           */
    0 40px 80px rgba(30, 41, 59, 0.08);    /* contact — far-field diffusion*/
  --prism-shadow-swatch:
    0 1px 2px   rgba(30, 41, 59, 0.06),
    0 8px 18px  rgba(30, 41, 59, 0.08),
    0 20px 40px rgba(30, 41, 59, 0.06);

  position: relative;
  min-height: 100vh;
  background: linear-gradient(135deg, var(--prism-bg) 0%, var(--prism-bg-deep) 100%);
  color: var(--prism-ink);
  font-family: "Inter", "Noto Sans KR", sans-serif;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.7;
  letter-spacing: -0.011em;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Refracted light washing across the studio — strong conic/radial blooms in
   spectrum hues, the room's ambient color cast. Pure CSS, paused under
   reduced motion. */
.prism-root::before {
  content: "";
  position: fixed;
  inset: -10%;
  z-index: 0;
  pointer-events: none;
  /* Seven spectrum blooms — red/orange/yellow/green/cyan/blue/violet — laid
     out as a dispersed rainbow, NOT a generic purple-blue gradient. This is
     the prism's whole point: white light split into spectrum. */
  background:
    radial-gradient(28% 32% at 12% 30%, rgba(239,68,68,0.34), transparent 60%),
    radial-gradient(26% 30% at 26% 22%, rgba(249,115,22,0.30), transparent 60%),
    radial-gradient(28% 32% at 40% 18%, rgba(234,179,8,0.30), transparent 60%),
    radial-gradient(28% 32% at 55% 22%, rgba(34,197,94,0.30), transparent 60%),
    radial-gradient(28% 32% at 70% 28%, rgba(6,182,212,0.32), transparent 60%),
    radial-gradient(28% 32% at 84% 38%, rgba(59,130,246,0.32), transparent 60%),
    radial-gradient(30% 34% at 92% 55%, rgba(139,92,246,0.28), transparent 60%);
  animation: prism-aurora 22s var(--prism-ease-spread) infinite alternate;
  filter: blur(14px);
}
@keyframes prism-aurora {
  to { transform: translate3d(4%, 3%, 0) scale(1.06); }
}
@media (prefers-reduced-motion: reduce) {
  .prism-root::before { animation: none; }
}

/* Korean needs its own metrics — Hangul never gets tracking fanned out. */
.prism-root :lang(ko) {
  font-family: "Noto Sans KR", sans-serif;
  letter-spacing: 0;
  line-height: 1.9;
  word-break: keep-all;
  word-wrap: break-word;
}
.prism-root ::selection { background: var(--prism-accent); color: #fff; }
.prism-root :focus-visible {
  outline: 2px solid var(--prism-accent-ink);
  outline-offset: 4px;
  border-radius: 2px;
}

.prism-js [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 900ms var(--prism-ease-reveal),
    transform 900ms var(--prism-ease-reveal);
}
.prism-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .prism-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.prism-doc { position: relative; z-index: 1; }

/* ==========================================================================
   Hero — the studio sign-in
   ========================================================================== */
.prism-hero {
  padding:
    clamp(80px, 16vh, 140px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 60px);
  text-align: center;
}
.prism-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--prism-accent-ink);
  margin: 0 0 var(--sp-8);
  text-wrap: pretty;
}
.prism-title {
  font-weight: 700;
  font-size: clamp(4rem, 14vw, 9rem);
  line-height: 0.9;
  letter-spacing: -0.04em;          /* display tracking — major glyph run   */
  margin: 0 0 var(--sp-5);
  display: flex;
  justify-content: center;
  gap: 0.02em;
}
/* char-split-reveal: each glyph in its spectrum color, staggered, with a
   prismatic chromatic-aberration glow (the light splitting through glass). */
.prism-glyph {
  display: inline-block;
  color: var(--prism-c, var(--prism-accent));
  opacity: 0;
  transform: translateY(30px) scale(0.8);
  font-weight: 800;
  text-shadow:
    -0.02em 0 0 rgba(255, 0, 80, 0.55),
    0.02em 0 0 rgba(0, 200, 255, 0.55),
    0 0 12px color-mix(in srgb, var(--prism-c, var(--prism-accent)) 55%, transparent),
    0 0 28px color-mix(in srgb, var(--prism-c, var(--prism-accent)) 30%, transparent);
}
.prism-js .prism-glyph {
  animation: prism-glyph-in 800ms var(--prism-ease-back) both;
  animation-delay: calc(var(--prism-i, 0) * 100ms + 200ms);
}
@keyframes prism-glyph-in {
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .prism-glyph { opacity: 1; transform: none; animation: none; }
}
.prism-sub {
  color: var(--prism-ink-soft);
  margin: 0;
  font-size: clamp(0.95rem, 1.6vw, 1.1rem);
  text-wrap: pretty;
}

/* ==========================================================================
   The prism stage — pointer-parallax glass panel
   Multi-layer shadow (ambient + key + contact) gives the glass real depth;
   the inner light edge reads as a beveled glass facet.
   ========================================================================== */
.prism-stage {
  position: relative;
  z-index: 1;
  padding:
    clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  max-width: 900px;
  margin: 0 auto;
  border-radius: 24px;
  background: var(--prism-glass);
  border: 1px solid var(--prism-glass-border);
  /* inner top highlight — the bright facet of a beveled glass edge */
  box-shadow:
    inset 0 1px 0 var(--prism-glass-edge),
    var(--prism-shadow-stage);
  -webkit-backdrop-filter: blur(20px) saturate(160%);
  backdrop-filter: blur(20px) saturate(160%);
  /* Individual properties, never `transition: all`. The parallax transform
     runs on the scrub curve; the lift on hover is a separate, faster one. */
  transition:
    transform 500ms var(--prism-ease-out),
    box-shadow 300ms var(--prism-ease-out);
  will-change: transform;
}
.prism-stage:hover {
  box-shadow:
    inset 0 1px 0 var(--prism-glass-edge),
    0 1px 2px   rgba(30, 41, 59, 0.05),
    0 18px 36px rgba(30, 41, 59, 0.12),
    0 56px 96px rgba(30, 41, 59, 0.10);
}
/* The generated spectrum-beam field — dispersed light behind the SVG
   diagram, so the glass stage reads as a real light-room. Soft, low-opacity,
   the line-draw refraction stays the focal diagram. */
.prism-stage__field {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 24px;
  opacity: 0.30;
  mix-blend-mode: multiply;
  z-index: 0;
  pointer-events: none;
}
.prism-beam-svg {
  position: relative;
  z-index: 1;
  width: 100%;
  height: auto;
  display: block;
  /* contact drop-shadow grounds the line drawing on the glass surface */
  filter: drop-shadow(0 12px 18px rgba(30, 41, 59, 0.10));
}

@media (prefers-reduced-motion: reduce) {
  .prism-stage { transform: none !important; transition: none; }
}
/* svg-line-draw: the beam + rays draw via stroke-dashoffset */
.prism-beam-in {
  stroke-dasharray: 300;
  stroke-dashoffset: 300;
  animation: prism-draw 1500ms var(--prism-ease-reveal) forwards;
  animation-delay: 400ms;
}
.prism-ray {
  stroke-dasharray: 420;
  stroke-dashoffset: 420;
  animation: prism-draw 1200ms var(--prism-ease-reveal) forwards;
  animation-delay: calc(var(--prism-ray-i, 0) * 80ms + 1000ms);
}
.prism-glass {
  opacity: 0;
  animation: prism-fade-in 600ms var(--prism-ease-out) forwards;
  animation-delay: 200ms;
}
@keyframes prism-draw { to { stroke-dashoffset: 0; } }
@keyframes prism-fade-in { to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .prism-beam-in, .prism-ray { stroke-dashoffset: 0; animation: none; }
  .prism-glass { opacity: 1; animation: none; }
}

/* ==========================================================================
   Spectrum legend — dispersing into data
   Each swatch carries wavelength (nm) and refractive index (crown glass n),
   so the legend reads as a lab chart, not just a rainbow.
   ========================================================================== */
.prism-spectrum {
  padding:
    clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  max-width: 900px;
  margin: 0 auto;
}
.prism-secthead {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--prism-accent-ink);
  margin: 0 0 var(--sp-10);
  text-wrap: pretty;
}
.prism-spectrum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: var(--sp-5);
}
.prism-color { text-align: center; }
.prism-color__swatch {
  display: block;
  width: 100%;
  height: 80px;
  border-radius: 12px;
  background: var(--prism-c);
  margin-bottom: var(--sp-3);
  /* 3-layer shadow keyed to each hue — swatch glows in its own color */
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--prism-c) 25%, transparent),
    0 8px 18px color-mix(in srgb, var(--prism-c) 30%, transparent),
    0 20px 40px color-mix(in srgb, var(--prism-c) 20%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.prism-color__ko {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin: 0 0 var(--sp-1);
  color: var(--prism-ink);
}
.prism-color__en {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--prism-ink-soft);
  margin: 0 0 var(--sp-2);
}
/* Lab data row — wavelength and refractive index, tabular for column scan */
.prism-color__data {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 0.7rem;
  font-variant-numeric: tabular-nums;
  color: var(--prism-ink-soft);
  letter-spacing: 0.02em;
  line-height: 1.45;
}
.prism-color__data b {
  font-weight: 500;
  color: var(--prism-ink);
}

/* ==========================================================================
   Footer
   ========================================================================== */
.prism-foot {
  padding:
    clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  color: var(--prism-ink-soft);
  font-size: 0.82rem;
  border-top: 1px solid var(--prism-glass-border);
  text-wrap: pretty;
}
.prism-foot p { margin: 0 0 var(--sp-2); }

/* ==========================================================================
   Responsive — honest at 360px, composed at 1440px+
   ========================================================================== */
@media (max-width: 720px) {
  .prism-hero { padding-bottom: var(--sp-8); }
  .prism-title { font-size: clamp(3rem, 18vw, 5rem); }
  .prism-spectrum-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--sp-4);
  }
  .prism-color__swatch { height: 64px; border-radius: 10px; }
  .prism-stage { padding: var(--sp-6) var(--sp-4); border-radius: 18px; }
}

@media (max-width: 900px) {
  .prism-spectrum-grid { grid-template-columns: repeat(3, 1fr); }
  .prism-secthead { margin-bottom: var(--sp-8); }
}

@media (min-width: 1200px) {
  /* On wide screens, let the studio breathe — wider stage, looser legend. */
  .prism-stage,
  .prism-spectrum { max-width: 1040px; }
  .prism-spectrum-grid {
    grid-template-columns: repeat(7, 1fr);
    gap: var(--sp-6);
  }
  .prism-color__swatch { height: 96px; }
}
